from author_library import *
cards=[]
c=compact('feili','费力','费力是有名的精神医学研究者，得到世界性研究基金资助，在海边拥有装置完善的研究所。他喜欢把自己的课题说得神秘，对外行的大胆猜测既不屑又被激怒，邀请梁若水做助手后又取消安排，令别人很难知道实验进展。两名现代人分别表现出李自成和建文帝的记忆与行为，使卫斯理等把他的工作解释成收集并移入古人记忆，也就是招魂；他却始终否认，称对病人的治疗没有成果。观察者取得的资料很强，却仍缺少可复现实验和他的完整说明，卡片不能把推理直接升格成已经公开的无条件技术。最后他亲自戴上头罩操作设备，电脑出现一组拼音，后来被认出是倪云林的别号；研究所留下一幅精妙新画和离去题字，他本人失踪超过半年。可能是古人记忆进入了他，可能原有记忆被覆盖，但没有目击者能确认两种人格如何延续。终局卡采用最后可确认的研究者形态与离去后的知识边界，不叠加倪云林全部人生，更不能凭一句盛怒中的话便随时制造任何名人。他的好奇、保密和以自身冒险的冲动，可以推动新的选择，也会使别人无法为他兜底。','《招魂》自体实验后失踪超过半年，是否由倪云林记忆取代原人格未证实；采用最后确认可自主行动的费力研究者形态','主角','突破脑活动与记忆研究的边界，同时掌握研究公开和使用的主动权','自负、好饮酒，面对外行追问容易讥讽，重视实验室的私人界线','秘密被窥探时愤怒否认，研究瓶颈时可能亲自承担高风险实验','设备观测与外界推断必须分开，别人不能因猜中部分机制就拥有全部解释权',[ab('脑活动与记忆实验','以大型电脑、头罩及研究设施记录和处理脑活动；观察到受试者的古人记忆表现','完整机制与稳定复现未公开；需设施和对象，不是裸身召来任意灵魂'),ab('医学与设备操作','受专业训练，能独立调节研究装置并识别曲线数据','不等于万能医学；自体实验可能影响原有身份，失踪后不能确认仍掌握全部操作')],[ev('077',71,190,'医师身份、性格和课题'),ev('077',419,425,'基金与研究所'),ev('077',4435,4558,'否认、受试者与无法完全证实'),ev('077',4622,4689,'自体实验、画作及失踪')],profile='expert')
rate(c,[1,3,2,3,3,3],neg=(2,3,2),tier='并',reason='记忆处理具有明显特殊效果，但依赖研究设备和受试者，终局身份未知；不计任意远程夺魂或所有古人技能。',mastery='稍有掌握')
c['uncertainties'].extend(['招魂机制主要为卫斯理等的推断，费力否认；观察证据支持异常，不证明每项推论。','倪云林式画作和别号提供强烈线索，未直接证实费力已经永久成为倪云林。'])
c['baseline']['energy']='疑似通过设备收集并输入记忆／灵魂信息；没有独立能量攻击和任意移走别人灵魂的证明。'
c['adaptations'].append({'change':'失踪后的部署采用最后可确认的研究者人格，不强行确立费力与倪云林融合','reason':'避免把开放结局偷换成无条件双人格技能包。','power_impact':'不增加画家技艺或任意召魂权限；若采用倪云林假说，须另设互斥版本。'})
cards.append(c)
cards.append(compact('jianwen_memory','承载建文帝记忆的人','这个现代成年人的原有身份不明，第一次被齐白遇见时却以落难皇帝自居，熟悉十万大山内隐蔽的避难居所，对宫廷生活、追捕与旧日恩怨有具体记忆。他会命人跪下，会因锦衣卫的名称惊惧，也会把现代访客放进自己仍然统治天下的想象里。外在威严和无处可逃的恐惧不断交替，既想保住尊严，又渴望知道自己为什么到了一个不认识的时代。他表现过用剑及伤害自己的冲动，卫斯理打了他一掌以后，他原先的语言、知识和性格突然消失，显出严重认知障碍，需要照料。齐白后来在真正旧墓中找到的遗骨与剑伤，使人怀疑他在重复一段外来的生命记忆，但身体不是历史皇帝的原身，费力也没有承认其来源。本卡把这段曾能自主表达的记忆人格作为可辨角色记录，终局明确已退出，不能给后来的照护对象继续安上皇帝意志。若参演，需单列恢复最后可表达的记忆状态这一改编，只保留本书展示的知识与情绪，不搬入现实史书中的全部帝王经历、军队或权威。','《招魂》受掌掴后建文记忆表现消失，现代身体存活并需照料；参演时明确恢复最后可独立表达的记忆形态','主角','在无法理解的时代中保住身份和安全，逃离被追捕的恐惧','时而自称帝王、要求礼数，时而露出落难者的惊惧和迷惘','听到追捕机构或被否认身份时强烈反应，可能重复记忆中的绝望行为','记忆中的权威不能支配现代他人，确认环境比立即命令更能保护自己',[ab('特定古人记忆','熟悉避难地形及宫廷旧事，能以相应身份语言交流','记忆来源未完全证实，历史知识不等于当前权位；曾在冲击后消失'),ab('有限用剑','能持现场古剑作出威胁或动作','没有完整剑法宗师展示，武器须实际取得，肉身仍是现代普通人')],[ev('077',2479,2639,'身份、时代冲突与记忆'),ev('077',2647,2736,'地形、追捕恐惧和帝王姿态'),ev('077',3550,3569,'认知状态变化'),ev('077',3611,3660,'遗骨与记忆假说')],profile='ordinary'))
cards[-1]['adaptations'].append({'change':'参演恢复最后可独立表达的建文记忆状态，并保留其后消失的终局知识','reason':'原作终局此人格已不再表达；必须把重现和本体照护状态分开。','power_impact':'不增加新技能，不把现代身体当作历史帝王复生的确证。'})
cards.append(compact('lizicheng_memory','承载李自成记忆的人','这名魁梧大汉在费力研究所的长柜抽屉中出现，身体受限，却突然以战场人物的口吻询问军情，表现出凛然气势。他看见两名红衣少女，把她们误认作红娘子及其姐妹，随即陷入悔恨，声称杀了李兄弟是自己一生最后悔的事，并表示愿让对方替夫报仇。这段对话触到良辰、美景隐藏的家族往事，使她们误以为整件事是针对自己的恶作剧。大汉并没有真的见到历史人物，眼前的少女也不是旧日关系的复活，错认本身就是他的局限。后来卫斯理等再次探访，他已神情呆滞、无法作相应回答，院长认出他是借给费力研究的病人。由此产生记忆输入与撤除的推论，却没有获得费力的承认或公开复验。卡片只记录曾经表达过的记忆人格，不将古人历史上的所有战争和罪行全部归给现代身体的原主人。终局需要照料的身体不被当作随时可战斗的豪杰；若要让这段人格在后日谈中行动，恢复其最后能自主表达的状态须明列为改编，仍不能附送起义军、王位或无证据的超常武艺。','《招魂》再次被带出时已无李自成式反应，现代身体仍在研究所照护；参演恢复最后可表达的记忆状态','主角','面对自身记忆中的失败与杀友悔恨，在错置的环境里寻找解释','魁梧有威势，语气在豪迈与末路悲凉间变化','红衣来客或复仇话语触发旧记忆时，会错认关系并愿承担惩罚','悔恨需要面对真实对象，不能把陌生人的外形自动当作旧人归来',[ab('特定军旅记忆与语言','表达关于旧战事和李岩之死的记忆情绪，能够交谈','来源、完整程度与真实性未完全证实，不等于拥有历史上全部指挥经验'),ab('魁梧肉身','有明显强健外形，曾在柜内坐起和挣扎','受现场束缚且无充分战斗展示；记忆退出后的认知状态不支持独立作战')],[ev('077',1000,1107,'错认、气势与悔恨'),ev('077',4519,4558,'再次出现及认知状态'),ev('077',4307,4324,'记忆机制为观察者推断')],profile='ordinary'))
cards[-1]['adaptations'].append({'change':'恢复最后能独立交谈的李自成记忆状态','reason':'该记忆在原作末已不再表现，后日谈不能隐瞒这种状态变化。','power_impact':'不恢复历史军队或未展示武艺，不认定现代身体原主人就是李自成。'})
save(cards)
cover('077',[('卫斯理','wei_sili','主角','调查及形成未完全证实的记忆假说'),('白素','bai_su','主角','分析、控制冲突及复核录像'),('齐白','qi_bai','主角','古墓见闻与画作辨识'),('梁若水','liang_ruoshui','重要配角','受邀助手及专业判断'),('良辰','liang_chen','重要配角','夜探、家族触动和监视录像'),('美景','mei_jing','重要配角','夜探、家族触动和监视录像'),('温宝裕','wen_baoyu','重要配角','分析并探访研究所'),('胡说','hu_shuo','重要配角','共同讨论和探访'),('费力','feili','主角','研究与自体实验失踪'),('建文记忆人格','jianwen_memory','主角','古墓行动和身份消失'),('李自成记忆人格','lizicheng_memory','主角','独立对话和异常认知线')],[('倪云林','仅画作与别号指向的未证实人格；不另建确定复生卡，与费力互斥假说记录'),('精神病院院长','一次性专业见证和受试者来源说明，未证实了解或合谋招魂'),('历史李白、李岩、红娘子、朱棣等','提及或记忆背景，不因名号建成本书活动的复生角色')],['费力否认，观察者承认不能完全证实；技术与灵魂解释保留推论等级。现代照护对象与输入记忆人格要区分，不使用原文侮辱性诊断词作为角色定义。'])
